const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, LevelFormat, BorderStyle } = require('docx');

// Helper to parse markdown bold/italic
function parseText(text) {
    // Split by **bold** or *italic*
    // Note: This is a simple parser and might not handle nested or complex cases perfectly
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map(part => {
        if (part.startsWith('**') && part.endsWith('**')) {
            return new TextRun({ text: part.slice(2, -2), bold: true });
        } else if (part.startsWith('*') && part.endsWith('*')) {
            return new TextRun({ text: part.slice(1, -1), italics: true });
        } else {
            return new TextRun({ text: part });
        }
    });
}

// Helper for paragraphs
function createPara(text, options = {}) {
    return new Paragraph({
        children: parseText(text),
        ...options
    });
}

// Define Numbering
const numbering = {
    config: [
        {
            reference: "mixed-list",
            levels: [
                {
                    level: 0,
                    format: LevelFormat.DECIMAL,
                    text: "%1.",
                    alignment: AlignmentType.LEFT,
                    style: { paragraph: { indent: { left: 720, hanging: 360 } } }
                },
                {
                    level: 1,
                    format: LevelFormat.BULLET,
                    text: "•",
                    alignment: AlignmentType.LEFT,
                    style: { paragraph: { indent: { left: 1440, hanging: 360 } } }
                },
                {
                    level: 2,
                    format: LevelFormat.BULLET,
                    text: "◦",
                    alignment: AlignmentType.LEFT,
                    style: { paragraph: { indent: { left: 2160, hanging: 360 } } }
                }
            ]
        },
        {
            reference: "bullet-only",
            levels: [
                {
                    level: 0,
                    format: LevelFormat.BULLET,
                    text: "•",
                    alignment: AlignmentType.LEFT,
                    style: { paragraph: { indent: { left: 720, hanging: 360 } } }
                }
            ]
        }
    ]
};

const children = [];

// Title
children.push(createPara("深度研究报告：陈材杰 (Chen Caijie) —— 从财经科普新星到前沿技术探索者", {
    heading: HeadingLevel.TITLE,
    alignment: AlignmentType.CENTER
}));

// Metadata
children.push(createPara("**报告日期：** 2026年1月9日"));
children.push(createPara("**研究员：** 幽浮喵 (Antigravity Agent)"));
children.push(createPara("**字数目标：** 深度长文"));
children.push(createPara("**关键词：** 财经科普、秒懂金融、知识付费、多模态情感识别、HetEmotionNet"));

children.push(new Paragraph({ text: "" }));
children.push(new Paragraph({ border: { bottom: { color: "auto", space: 1, style: BorderStyle.SINGLE, size: 6 } } }));
children.push(new Paragraph({ text: "" }));

// 摘要
children.push(createPara("摘要 (Executive Summary)", { heading: HeadingLevel.HEADING_2 }));
children.push(createPara("本报告旨在对“陈材杰”这一研究对象进行全方位的深度画像。通过公开数据挖掘与情报关联分析，我们发现“陈材杰”并非单指某一特定领域的单一人物，而在当前互联网公开语境下，主要指向两位在该领域具有显著代表性的杰出人士：一位是凭借《秒懂金融》在中文互联网财经科普领域异军突起的**青年财经学者与畅销书作家陈材杰**；另一位是活跃于计算机视觉与人工智能领域的**北京交通大学研究学者 Caijie Chen**。"));
children.push(createPara("本报告将采取双轨并行的叙事结构，第一部分重点剖析财经作家陈材杰的知识传播方法论、著作核心价值及其在“理财热”背景下的社会影响力；第二部分则深入解读科研学者 Caijie Chen 在多模态情感识别（MER）领域的算法创新与学术贡献。报告力求通过详实的数据支撑与深度的逻辑推演，为读者呈现一个立体、客观且极具参考价值的研究文本。"));

children.push(new Paragraph({ text: "" }));
children.push(new Paragraph({ border: { bottom: { color: "auto", space: 1, style: BorderStyle.SINGLE, size: 6 } } }));
children.push(new Paragraph({ text: "" }));

// Chapter 1
children.push(createPara("第一章：多维视域下的“陈材杰”人物图谱", { heading: HeadingLevel.HEADING_2 }));
children.push(createPara("在正式进入深度分析之前，有必要对“陈材杰”这一符号进行语义消歧。基于开源情报（OSINT）的检索结果，我们构建了以下人物图谱："));

// List 1
children.push(createPara("**核心关注对象 A（财经领域）：**", { numbering: { reference: "mixed-list", level: 0 } }));
children.push(createPara("**身份：** 国家高端智库青年研究人员、小红书头部财经博主、“秒懂金融”主理人、畅销书作家。", { numbering: { reference: "mixed-list", level: 1 } }));
children.push(createPara("**标签：** 跨界通才（工科转金融）、视觉化科普、降维打击。", { numbering: { reference: "mixed-list", level: 1 } }));
children.push(createPara("**代表作：** 《秒懂金融：把复杂的金融学变简单》。", { numbering: { reference: "mixed-list", level: 1 } }));

children.push(createPara("**核心关注对象 B（学术领域）：**", { numbering: { reference: "mixed-list", level: 0 } }));
children.push(createPara("**身份：** 研究学者（隶属于北京交通大学计算机与信息技术学院）。", { numbering: { reference: "mixed-list", level: 1 } }));
children.push(createPara("**标签：** 人工智能、深度学习、情感计算。", { numbering: { reference: "mixed-list", level: 1 } }));
children.push(createPara("**代表作：** *HetEmotionNet: Two-Stream Heterogeneous Graph Recurrent Neural Network for Multi-modal Emotion Recognition*。", { numbering: { reference: "mixed-list", level: 1 } }));

children.push(createPara("**其他同名人物（边缘关联）：**", { numbering: { reference: "mixed-list", level: 0 } }));
children.push(createPara("**运动员：** 中国田径运动员（半程马拉松选手），在世界田联（World Athletics）有注册记录。", { numbering: { reference: "mixed-list", level: 1 } }));

children.push(createPara("本报告将聚焦于前两位在各自智力密集型领域取得显著成就的人物。"));

children.push(new Paragraph({ text: "" }));
children.push(new Paragraph({ border: { bottom: { color: "auto", space: 1, style: BorderStyle.SINGLE, size: 6 } } }));
children.push(new Paragraph({ text: "" }));

// Chapter 2
children.push(createPara("第二章：陈材杰（财经科普专家）—— 复杂金融知识的“翻译官”", { heading: HeadingLevel.HEADING_2 }));
children.push(createPara("在当今信息爆炸且金融产品日益复杂的时代，公众对于高质量、低门槛的金融知识需求呈井喷式增长。陈材杰正是这一背景下涌现出的现象级科普专家。"));

children.push(createPara("2.1 个人成长路径与职业背景复盘", { heading: HeadingLevel.HEADING_3 }));

children.push(createPara("2.1.1 独特的“工科+金融”复合背景", { heading: HeadingLevel.HEADING_4 }));
