children.push(createPara("**股票：** 摒弃了复杂的K线技术分析，转而强调“公司视角”。通过财报分析（ROE、毛利率、现金流）来判断企业的真实价值，倡导价值投资理念。", { numbering: { reference: "mixed-list-2", level: 1 } }));

children.push(createPara("**宏观经济篇（格局的打开）：** 解释了GDP、CPI、PPI等宏观指标与个人就业、房产价值的联动关系。例如，通过美林时钟（Investment Clock）理论，指导读者在经济周期的不同阶段配置不同资产。", { numbering: { reference: "mixed-list-2", level: 0 } }));

children.push(createPara("2.2.2 核心方法论：降维打击式的“视觉化叙事”", { heading: HeadingLevel.HEADING_4 }));
children.push(createPara("陈材杰最显著的特征在于其“视觉化”能力。书名“秒懂”并非夸大其词，而是基于精心设计的信息可视化图表。"));
children.push(createPara("**类比思维（Analogy）：** 他极少直接堆砌定义。例如讲“做空”，他可能会用“借邻居的酱油先卖掉，等酱油便宜了再买回来还给邻居”这种极其生活化的例子，瞬间让复杂的金融操作去魅。", { numbering: { reference: "bullet-only", level: 0 } }));
children.push(createPara("**图表叙事（Visual Storytelling）：** 他的书中充斥着大量的流程图、对比图和思维导图。这些图表不是文字的附庸，而是信息的载体。对于习惯了碎片化阅读的现代读者，这种“读图时代”的表达方式具有极强的穿透力。", { numbering: { reference: "bullet-only", level: 0 } }));

children.push(createPara("2.3 社会价值与影响力评估", { heading: HeadingLevel.HEADING_3 }));
