children.push(createPara("第三章：Caijie Chen（计算机科学家）—— 情感计算的探路者", { heading: HeadingLevel.HEADING_2 }));
children.push(createPara("在另一个平行宇宙中，名为 Caijie Chen 的学者正在人工智能的前沿领域——情感计算（Affective Computing）探索着机器理解人类情感的可能性。"));

children.push(createPara("3.1 学术背景与研究阵地", { heading: HeadingLevel.HEADING_3 }));
children.push(createPara("Caijie Chen 隶属于**北京交通大学（BJTU）计算机与信息技术学院**。北京交通大学计算机学科在交通大数据、人工智能及网络科学领域拥有深厚的积淀。Caijie Chen 的研究方向主要集中在："));
children.push(createPara("**多模态学习（Multi-modal Learning）：** 融合文本、音频、视觉等多种数据源进行综合分析。", { numbering: { reference: "bullet-only", level: 0 } }));
children.push(createPara("**图神经网络（Graph Neural Networks, GNN）：** 利用图结构处理非欧几里得空间的数据关系。", { numbering: { reference: "bullet-only", level: 0 } }));
children.push(createPara("**情感识别（Emotion Recognition）：** 让机器通过分析人的语音语调、面部表情和文本内容，判断其情感状态（如快乐、悲伤、愤怒、中性等）。", { numbering: { reference: "bullet-only", level: 0 } }));

children.push(createPara("3.2 核心成果解构：HetEmotionNet", { heading: HeadingLevel.HEADING_3 }));
